            unsigned long max_length = 256;
            char domain[256] = { 0 };
            if (!GetComputerNameExA(ComputerNameDnsFullyQualified, domain, &max_length)) {
                #ifdef _DEBUG_
                wprintf(L"ERROR: GetComputerNameExA = 0x%x\n", GetLastError());
                #endif
            } else {
                #ifdef _DEBUG_
                wprintf(L"GetComputerNameExA = %s\n", domain);
                #endif
            }

